:root {
  color-scheme: dark;
}

* {
  box-sizing: border-box;
}

html,body {
  margin: 0;
  min-height: 100%;
  background: #020617;
  font-family: system-ui,-apple-system,Segoe UI,Roboto,sans-serif;
}

.main {
  min-height: 100vh;
  display: grid;
  place-items: center;
  padding: 24px;
  color: #e5e7eb;
}

.section {
  width: min(100%,620px);
  display: grid;
  gap: 16px;
}

.section h1 {
  margin: 0;
  font-size: 22px;
}

.card {
  display: grid;
  gap: 14px;
  padding: 18px;
  border: 1px solid #334155;
  border-radius: 16px;
  background: #0b1020;
}

.input-row {
  display: flex;
  gap: 8px;
}

.input {
  min-width: 0;
  flex: 1;
  padding: 10px 12px;
  border: 1px solid #475569;
  border-radius: 10px;
  background: #020617;
  color: #f8fafc;
}

.input:focus,.edit-input:focus,button:focus-visible {
  outline: 3px solid #facc15;
  outline-offset: 2px;
}

.primary,.filter-button,.ghost,.undo-button {
  border: 0;
  border-radius: 9px;
  padding: 9px 12px;
  font-weight: 700;
  cursor: pointer;
}

.primary {
  background: #a3e635;
  color: #172554;
}

.primary:disabled,.clear-completed:disabled {
  opacity: .45;
  cursor: not-allowed;
}

.instructions {
  margin: 0;
  color: #94a3b8;
  font-size: 12px;
}

.list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  gap: 8px;
}

.item {
  display: grid;
  grid-template-columns: minmax(0,1fr) auto;
  align-items: center;
  gap: 10px;
  padding: 10px;
  border: 1px solid #1e293b;
  border-radius: 11px;
  background: #020617;
}

.item-main {
  min-width: 0;
  display: flex;
  align-items: center;
  gap: 9px;
}

.todo-checkbox {
  inline-size: 18px;
  block-size: 18px;
  accent-color: #84cc16;
}

.todo-text {
  overflow-wrap: anywhere;
}

.todo-text.done {
  text-decoration: line-through;
  color: #94a3b8;
}

.item-actions {
  display: flex;
  gap: 6px;
}

.ghost,.filter-button {
  border: 1px solid #475569;
  background: transparent;
  color: #e2e8f0;
}

.edit-input {
  width: 100%;
  padding: 7px 9px;
  border: 1px solid #64748b;
  border-radius: 8px;
  background: #111827;
  color: #f8fafc;
}

.empty {
  margin: 0;
  padding: 12px;
  text-align: center;
  color: #94a3b8;
}

.footer {
  display: grid;
  gap: 10px;
}

.filters {
  display: flex;
  flex-wrap: wrap;
  gap: 7px;
}

.filter-button[aria-pressed="true"] {
  border-color: #a3e635;
  background: #365314;
  color: #ecfccb;
}

.footer-row {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
}

.items-left {
  margin: 0;
  color: #cbd5e1;
  font-size: 13px;
}

.clear-completed {
  padding: 7px 10px;
}

.undo-bar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 10px 12px;
  border: 1px solid #ca8a04;
  border-radius: 10px;
  background: #422006;
  color: #fef9c3;
}

.undo-button {
  background: #facc15;
  color: #422006;
}

.visually-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0,0,0,0);
  white-space: nowrap;
  border: 0;
}

@media (max-width:520px) {
  .main {
    padding: 14px;
  }

  .input-row {
    align-items: stretch;
    flex-direction: column;
  }

  .item {
    grid-template-columns: 1fr;
  }

  .item-actions {
    justify-content: flex-end;
  }
}
